import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"v3.2 归档","description":"AgoraIn v3.2（AgoraInPro）历史文档归档","frontmatter":{"title":"v3.2 归档","description":"AgoraIn v3.2（AgoraInPro）历史文档归档"},"headers":[],"relativePath":"v3.2/index.md","filePath":"v3.2/index.md","lastUpdated":1791175383000}'),l={name:"v3.2/index.md"};function o(i,t,h,n,s,v){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="v3-2-归档文档" tabindex="-1">v3.2 归档文档 <a class="header-anchor" href="#v3-2-归档文档" aria-label="Permalink to &quot;v3.2 归档文档&quot;">​</a></h1><blockquote><p>本区为 <strong>AgoraIn v3.2（AgoraInPro）</strong> 的历史文档，仅作留存与迁移参考。 新版本请访问 <a href="/">AgoraIn v4 官网</a>（课堂签到与教学管理一体化平台）。</p></blockquote><h2 id="v3-2-是什么" tabindex="-1">v3.2 是什么 <a class="header-anchor" href="#v3-2-是什么" aria-label="Permalink to &quot;v3.2 是什么&quot;">​</a></h2><p>AgoraIn v3.2 在一个窗口内提供<strong>大屏模式</strong>（课堂签到打卡）与<strong>控制模式</strong>（呼叫面板、课时划消与排课、 集控平台），配套集控服务器与移动端 App，并提供 <strong>ClassIsland 联动插件</strong>：教室一体机接收教师端呼叫， 以置顶弹窗 + 中文语音朗读提醒。</p><table tabindex="0"><thead><tr><th>模块</th><th>说明</th></tr></thead><tbody><tr><td>大屏模式</td><td>班级电子白板大屏签到，点击学生姓名完成打卡，前三名金 / 银 / 铜高亮</td></tr><tr><td>控制模式</td><td>呼叫面板（待下课 / 应急 / 传唤）、课时划消与排课、集控平台</td></tr><tr><td>集控服务器</td><td>多设备数据集中管理，Web 管理面板，平台配置持久化自动重连</td></tr><tr><td>ClassIsland 插件</td><td>一体机端接收呼叫，置顶弹窗 + 中文语音朗读</td></tr><tr><td>移动端</td><td>微信小程序 + Android + iOS / macOS 客户端</td></tr></tbody></table><p>技术栈：桌面端 WPF（.NET 10）· 移动端 .NET MAUI · 服务端 ASP.NET Core · 数据库 SQLite。</p><h2 id="归档文档" tabindex="-1">归档文档 <a class="header-anchor" href="#归档文档" aria-label="Permalink to &quot;归档文档&quot;">​</a></h2><ul><li><a href="/v3.2/features.html">功能特性</a></li><li><a href="/v3.2/guide.html">快速开始</a></li><li><a href="/v3.2/manual.html">使用手册</a></li><li><a href="/v3.2/api.html">API 文档</a></li><li><a href="/v3.2/deploy.html">部署指南</a></li><li><a href="/v3.2/server.html">服务器端</a></li><li><a href="/v3.2/plugin.html">一体机插件</a></li><li><a href="/v3.2/faq.html">常见问题</a></li><li><a href="/v3.2/sitemap.html">站点地图</a></li></ul><h2 id="版本关系" tabindex="-1">版本关系 <a class="header-anchor" href="#版本关系" aria-label="Permalink to &quot;版本关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>许可</th><th>状态</th></tr></thead><tbody><tr><td>v4（当前）</td><td>闭源商业授权</td><td>持续开发，推荐使用</td></tr><tr><td>v3.2</td><td>GPLv3</td><td>归档，仅维护文档</td></tr><tr><td>v2.8 / v2.7</td><td>GPLv3</td><td><a href="/v2.8/">v2.8</a> · <a href="/v2.7/">v2.7</a></td></tr></tbody></table>',10)])])}const m=a(l,[["render",o]]);export{c as __pageData,m as default};
